		const dayNumber = (d) => Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000)
		const dueDateServices = await services({ codeType: 'CD-GYNECOLOGY', code: 'duedate', limit: 3 })
		if (!dueDateServices.length) { resolve(undefined); return }
